var attachmentDomainSchema = import_zod.z.enum(["chat", "assistant", "support"]);
var attachmentMimeSchema = import_zod.z.enum(ATTACHMENT_MIME_TYPES);
var attachmentIdListSchema = import_zod.z.array(import_zod.z.string().uuid()).max(ATTACHMENT_LIMITS.messageFiles).refine((ids) => new Set(ids).size === ids.length, "Attachment IDs must be unique");
var attachmentUploadSchema = import_zod.z.object({
  name: import_zod.z.string().trim().min(1).max(240).refine(
    (name) => !Array.from(name).some(
      (char) => char.charCodeAt(0) < 32 || char.charCodeAt(0) === 127 || char === "/" || char === "\\"
    ),
    "Invalid filename"
  ),
  mime: attachmentMimeSchema,
  size: import_zod.z.number().int().positive().max(ATTACHMENT_LIMITS.videoBytes)
}).strict().refine(
  ({ mime, size }) => size <= (mime.startsWith("video/") ? ATTACHMENT_LIMITS.videoBytes : ATTACHMENT_LIMITS.fileBytes),
  "File exceeds size limit"
).refine(
  ({ name }) => !/\.(?:html?|svg|exe|dll|bat|cmd|scr|com|msi|zip|rar|7z|xlsm|docm|pptm)$/i.test(name),
  "Unsupported filename extension"
).refine(
  ({ mime, size }) => !mime.startsWith("image/") || size <= ATTACHMENT_LIMITS.imageBytes,
  "Image exceeds size limit"
);
var attachmentSummarySchema = import_zod.z.object({
  id: import_zod.z.string().uuid(),
  conversationId: import_zod.z.string().uuid(),
  domain: attachmentDomainSchema,
  name: import_zod.z.string().min(1).max(240),
  mime: attachmentMimeSchema,
  size: import_zod.z.number().int().nonnegative(),
  state: import_zod.z.enum(ATTACHMENT_STATES),
  version: import_zod.z.number().int().positive(),
  createdAt: import_zod.z.number().int().nonnegative(),
  expiresAt: import_zod.z.number().int().nonnegative(),
  errorCode: import_zod.z.enum(ATTACHMENT_ERRORS).nullable(),
  width: import_zod.z.number().int().positive().nullable(),
  height: import_zod.z.number().int().positive().nullable(),
  pages: import_zod.z.number().int().positive().nullable(),
  previews: import_zod.z.array(import_zod.z.enum(["thumbnail", "image", "text", "pdf"])),
  messageId: import_zod.z.string().uuid().nullable()
}).strict();
var attachmentManifestSchema = import_zod.z.object({
  id: import_zod.z.string().uuid(),
  name: import_zod.z.string().max(240),
  mime: attachmentMimeSchema,
  size: import_zod.z.number().int().positive().max(ATTACHMENT_LIMITS.fileBytes),
  sha256: import_zod.z.string().regex(/^[a-f0-9]{64}$/),
  pages: import_zod.z.array(import_zod.z.number().int().positive()).max(ATTACHMENT_LIMITS.pdfPages).optional()
}).strict();
var attachmentDerivativeSchema = import_zod.z.object({
  kind: import_zod.z.enum(["thumbnail", "image", "text", "pdf"]),
  key: import_zod.z.string().min(1).max(1024),
  sha256: import_zod.z.string().regex(/^[a-f0-9]{64}$/),
  size: import_zod.z.number().int().nonnegative().max(ATTACHMENT_LIMITS.fileBytes),
  mime: import_zod.z.string().max(128)
}).strict();
var attachmentStoredSchema = import_zod.z.object({
  summary: attachmentSummarySchema,
  uploaderId: import_zod.z.string().min(1).max(128),
  attemptId: import_zod.z.string().uuid().nullable(),
  objectKey: import_zod.z.string().max(1024).nullable(),
  sha256: import_zod.z.string().regex(/^[a-f0-9]{64}$/).nullable(),
  derivatives: import_zod.z.array(attachmentDerivativeSchema).max(4)
}).strict();
var attachmentPageSchema = import_zod.z.object({
  items: import_zod.z.array(attachmentSummarySchema),
  nextCursor: import_zod.z.string().nullable()
});
var attachmentProcessingSchema = import_zod.z.object({
  mime: attachmentMimeSchema,
  sha256: import_zod.z.string().regex(/^[a-f0-9]{64}$/),
  width: import_zod.z.number().int().positive().max(4e4).nullable(),
  height: import_zod.z.number().int().positive().max(4e4).nullable(),
  pages: import_zod.z.number().int().positive().max(ATTACHMENT_LIMITS.pdfPages).nullable(),
  scannerVersion: import_zod.z.string().min(1).max(128),
  derivatives: import_zod.z.array(
    import_zod.z.object({
      kind: import_zod.z.enum(["thumbnail", "image", "text", "pdf"]),
      mime: import_zod.z.string().max(128),
      data: import_zod.z.string().max(24 * 1024 * 1024)
    }).strict()
  ).max(4)
}).strict();
var attachmentPdfPreviewSchema = import_zod.z.object({
  totalPages: import_zod.z.number().int().positive().max(1e4),
  pages: import_zod.z.array(
    import_zod.z.object({
      page: import_zod.z.number().int().positive(),
      data: import_zod.z.string().regex(/^[A-Za-z0-9+/]*={0,2}$/).max(2 * 1024 * 1024)
    }).strict()
  ).min(1).max(100)
}).strict();
var attachmentModelBlockSchema = import_zod.z.discriminatedUnion("type", [
  import_zod.z.object({ type: import_zod.z.literal("text"), text: import_zod.z.string().max(ATTACHMENT_LIMITS.textBytes + 1024) }).strict(),
  import_zod.z.object({
    type: import_zod.z.literal("image"),
    mime: import_zod.z.enum(["image/jpeg", "image/png", "image/webp"]),
    data: import_zod.z.string().max(24 * 1024 * 1024)
  }).strict(),
  import_zod.z.object({
    type: import_zod.z.literal("document"),
    mime: import_zod.z.literal("application/pdf"),
    data: import_zod.z.string().max(24 * 1024 * 1024),
    name: import_zod.z.string().max(240),
    textBytes: import_zod.z.number().int().nonnegative().max(ATTACHMENT_LIMITS.modelFileTextBytes).optional()
  }).strict()
]);
var attachmentModelMessagesSchema = import_zod.z.array(
  import_zod.z.object({
    messageId: import_zod.z.string().uuid(),
    blocks: import_zod.z.array(attachmentModelBlockSchema).max(ATTACHMENT_LIMITS.messageFiles * (ATTACHMENT_LIMITS.pdfPages * 2 + 2))
  }).strict()
).max(100);
var attachmentPolicySchema = import_zod.z.object({
  uploadsEnabled: import_zod.z.boolean(),
  modelInputEnabled: import_zod.z.boolean(),
  types: import_zod.z.array(attachmentMimeSchema),
  limits: import_zod.z.object({
    imageBytes: import_zod.z.number().int().positive(),
    fileBytes: import_zod.z.number().int().positive(),
    messageBytes: import_zod.z.number().int().positive(),
    messageFiles: import_zod.z.number().int().positive(),
    pdfPages: import_zod.z.number().int().positive(),
    modelFiles: import_zod.z.number().int().positive(),
    modelImages: import_zod.z.number().int().positive(),
    modelPdfPages: import_zod.z.number().int().positive(),
    modelEncodedBytes: import_zod.z.number().int().positive(),
    modelTextBytes: import_zod.z.number().int().positive(),
    modelFileTextBytes: import_zod.z.number().int().positive()
  }).strict()
}).strict();

